const e = React.createElement;
const clamp = {extrapolateLeft:'clamp',extrapolateRight:'clamp'};
const sf = (a,b) => [a, Math.max(a+1,b)];
const cx = width * 0.5;
const cy = height * 0.5;

const iceOp = interpolate(frame, sf(0,45), [0.5, 0], clamp);
const iceSlide = interpolate(frame, sf(0,45), [0, 80], clamp);

const cardOp = interpolate(frame, sf(36,66), [0, 1], clamp);
const cardSc = interpolate(frame, sf(36,66), [0.92, 1], clamp);

const l1Op = interpolate(frame, sf(75,108), [0, 1], clamp);
const l1Y = interpolate(frame, sf(75,108), [30, 0], clamp);

const l2Spr = frame > 150 ? spring({frame:frame-150, fps, config:{damping:12, stiffness:160}}) : 0;

const l3Op = interpolate(frame, sf(240,275), [0, 1], clamp);
const l3Y = interpolate(frame, sf(240,275), [20, 0], clamp);

const vaultIn = interpolate(frame, sf(248,290), [0, 0.2], clamp);
const vaultHold = frame < 350 ? 1 : interpolate(frame, sf(350,400), [1, 0], clamp);
const vaultOp = vaultIn * vaultHold;
const vaultRot = interpolate(frame, sf(248,400), [0, 18], clamp);

const l4Spr = frame > 360 ? spring({frame:frame-360, fps, config:{damping:10, stiffness:140}}) : 0;
const glw = interpolate(frame, sf(380,460), [0, 30], clamp);
const breath = frame > 430 ? 1 + 0.006 * Math.sin((frame - 430) * 0.04) : 1;

const iceberg = e('div', {style:{
  position:'absolute', left:cx-130, top:cy-220+iceSlide,
  opacity:iceOp, pointerEvents:'none'
}},
  e('div',{style:{
    width:0,height:0,
    borderLeft:'65px solid transparent',
    borderRight:'65px solid transparent',
    borderBottom:'90px solid '+D.cyan,
    marginLeft:65, opacity:0.7, filter:'blur(1px)'
  }}),
  e('div',{style:{
    width:0,height:0,
    borderLeft:'130px solid transparent',
    borderRight:'130px solid transparent',
    borderBottom:'200px solid '+D.cyan,
    opacity:0.25, filter:'blur(2px)'
  }})
);

const vs = 340;
const spokeEls = Array.from({length:8},function(_,i){
  var ang = i*45*Math.PI/180;
  return e('div',{key:'s'+i,style:{
    position:'absolute',
    left:vs/2-2, top:vs/2,
    width:4, height:vs*0.38,
    background:D.cyan, borderRadius:2,
    transformOrigin:'2px 0',
    transform:'rotate('+ang+'rad)'
  }});
});

const vault = e('div',{style:{
  position:'absolute',
  left:cx-vs/2, top:cy-vs/2+10,
  width:vs, height:vs,
  opacity:vaultOp,
  transform:'rotate('+vaultRot+'deg)',
  pointerEvents:'none'
}},
  e('div',{style:{position:'absolute',inset:0,borderRadius:'50%',border:'3px solid '+D.cyan}}),
  e('div',{style:{position:'absolute',left:vs*0.3,top:vs*0.3,width:vs*0.4,height:vs*0.4,borderRadius:'50%',border:'2px solid '+D.cyan}}),
  e('div',{style:{position:'absolute',left:vs/2-12,top:vs/2-12,width:24,height:24,borderRadius:'50%',background:D.cyan}}),
  ...spokeEls
);

const cardW = 860;
const cardH = 460;
const card = e('div',{style:{
  position:'absolute',
  left:cx-cardW/2, top:cy-cardH/2,
  width:cardW, height:cardH,
  background:D.surface,
  borderRadius:20,
  border:'1px solid '+D.text_dim,
  opacity:cardOp,
  transform:'scale('+cardSc+')',
  display:'flex', flexDirection:'column',
  alignItems:'center', justifyContent:'center',
  gap:24, padding:40, boxSizing:'border-box'
}},
  e('div',{style:{
    fontFamily:D.font_display, fontSize:38, color:D.white,
    letterSpacing:2, textAlign:'center',
    opacity:l1Op, transform:'translateY('+l1Y+'px)'
  }},'SIGNING CONTRACTS THIS QUARTER?'),
  e('div',{style:{
    fontFamily:D.font_display, fontSize:49, color:D.amber,
    fontWeight:'bold', letterSpacing:3, textAlign:'center',
    opacity:l2Spr, transform:'scale('+(0.4+l2Spr*0.6)+')'
  }},'BUILD IN FLEXIBILITY.'),
  e('div',{style:{
    fontFamily:D.font_display, fontSize:30, color:D.white,
    letterSpacing:1, textAlign:'center',
    opacity:l3Op, transform:'translateY('+l3Y+'px)'
  }},'WHEN THIS DOOR OPENS FOR EVERYONE,'),
  e('div',{style:{
    fontFamily:D.font_display, fontSize:50, color:D.green,
    fontWeight:'bold', letterSpacing:4, textAlign:'center',
    opacity:l4Spr,
    transform:'scale('+(0.5+l4Spr*0.5)*breath+')',
    textShadow:'0 0 '+glw+'px '+D.green+', 0 0 '+(glw*2)+'px '+D.green
  }},'EVERYTHING CHANGES.')
);

return e('div',{style:{position:'absolute',inset:0,background:D.bg,overflow:'hidden'}},
  e('div',{style:{
    position:'absolute',inset:0,
    backgroundImage:'radial-gradient('+D.text_dim+' 1px, transparent 1px)',
    backgroundSize:D.dot_grid_spacing+'px '+D.dot_grid_spacing+'px',
    opacity:D.dot_grid_opacity
  }}),
  iceberg,
  card,
  vault
);
